local MoldDryingStandMaker = {}
local PRODUCTS = {
    iron_molddryingstand = { name = "Železni stojalo za sušenje kalupov", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni stojalo za sušenje kalupov za livarje." },
    bronze_molddryingstand = { name = "Bronast stojalo za sušenje kalupov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast stojalo za sušenje kalupov za livarje." },
    silver_molddryingstand = { name = "Srebrn stojalo za sušenje kalupov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn stojalo za sušenje kalupov za livarje." },
    gilded_molddryingstand = { name = "Pozlačen stojalo za sušenje kalupov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen stojalo za sušenje kalupov za livarje." },
    jewel_set_molddryingstand = { name = "Draguljast stojalo za sušenje kalupov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast stojalo za sušenje kalupov za livarje." },
    royal_sovereign_molddryingstand = { name = "Kraljevski suveren stojalo za sušenje kalupov", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren stojalo za sušenje kalupov z biseri za krono." },
}
local BUILDINGS = {
    molddryingstand_workshop = { name = "Molddryingstand delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    molddryingstand_house = { name = "Molddryingstand hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_molddryingstand_atelier = { name = "Mojstrski molddryingstand atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_molddryingstand_palace = { name = "Suverena molddryingstand palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MoldDryingStandMaker.ironStock=14; MoldDryingStandMaker.bronzeStock=12; MoldDryingStandMaker.woodStock=14; MoldDryingStandMaker.leatherStock=8; MoldDryingStandMaker.silverStock=8; MoldDryingStandMaker.goldStock=6; MoldDryingStandMaker.jewelStock=4; MoldDryingStandMaker.pearlStock=4
MoldDryingStandMaker.productStock = {}; MoldDryingStandMaker.buildings = {}; MoldDryingStandMaker.maker = nil; MoldDryingStandMaker.activeMaking = {}; MoldDryingStandMaker.totalProducts = 0; MoldDryingStandMaker.dayTimer = 0
function MoldDryingStandMaker.init() MoldDryingStandMaker.ironStock=14; MoldDryingStandMaker.bronzeStock=12; MoldDryingStandMaker.woodStock=14; MoldDryingStandMaker.leatherStock=8; MoldDryingStandMaker.silverStock=8; MoldDryingStandMaker.goldStock=6; MoldDryingStandMaker.jewelStock=4; MoldDryingStandMaker.pearlStock=4; MoldDryingStandMaker.productStock={}; MoldDryingStandMaker.buildings={}; MoldDryingStandMaker.maker=nil; MoldDryingStandMaker.activeMaking={}; MoldDryingStandMaker.totalProducts=0; MoldDryingStandMaker.dayTimer=0; print("[MoldDryingStandMaker] Royal Mold Drying Stand Maker System initialized (6 products, 4 buildings)") end
function MoldDryingStandMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MoldDryingStandMaker.maker={name=n or ("Stojalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalnik najet: %s (spretnost: %d)",MoldDryingStandMaker.maker.name,s),"success") end; return true end
function MoldDryingStandMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MoldDryingStandMaker.build(id) local ok,e=MoldDryingStandMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MoldDryingStandMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MoldDryingStandMaker.getQualityBonus() local b=0; for _,bd in ipairs(MoldDryingStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MoldDryingStandMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MoldDryingStandMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MoldDryingStandMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MoldDryingStandMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MoldDryingStandMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MoldDryingStandMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MoldDryingStandMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MoldDryingStandMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MoldDryingStandMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MoldDryingStandMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not MoldDryingStandMaker.maker then return false,"Potreben stojalnik" end; return true end
function MoldDryingStandMaker.make(pt,qty) qty=qty or 1; local ok,e=MoldDryingStandMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MoldDryingStandMaker.ironStock=MoldDryingStandMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MoldDryingStandMaker.bronzeStock=MoldDryingStandMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MoldDryingStandMaker.woodStock=MoldDryingStandMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MoldDryingStandMaker.leatherStock=MoldDryingStandMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MoldDryingStandMaker.silverStock=MoldDryingStandMaker.silverStock-d.silverCost*qty end; if d.goldCost then MoldDryingStandMaker.goldStock=MoldDryingStandMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MoldDryingStandMaker.jewelStock=MoldDryingStandMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MoldDryingStandMaker.pearlStock=MoldDryingStandMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MoldDryingStandMaker.maker then t=math.max(1,t-math.floor(MoldDryingStandMaker.maker.skill/13)) end; table.insert(MoldDryingStandMaker.activeMaking,{id="molddryingstand_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MoldDryingStandMaker.completeMaking(m) local q=1.0+(MoldDryingStandMaker.getQualityBonus()/100); if MoldDryingStandMaker.maker then q=q+(MoldDryingStandMaker.maker.skill/140) end; q=math.min(2.5,q); MoldDryingStandMaker.productStock[m.productType]=(MoldDryingStandMaker.productStock[m.productType] or 0)+m.quantity; MoldDryingStandMaker.totalProducts=MoldDryingStandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldDryingStandMaker.maker then MoldDryingStandMaker.maker.itemsMade=MoldDryingStandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldDryingStandMaker.maker.skill=math.min(100,MoldDryingStandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"molddryingstand.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MoldDryingStandMaker.update(dt) if not _G.state then return end; MoldDryingStandMaker.dayTimer=MoldDryingStandMaker.dayTimer+dt; if MoldDryingStandMaker.dayTimer>=30 then MoldDryingStandMaker.dayTimer=0; for i=#MoldDryingStandMaker.activeMaking,1,-1 do local m=MoldDryingStandMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MoldDryingStandMaker.completeMaking(m); table.remove(MoldDryingStandMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MoldDryingStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MoldDryingStandMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MoldDryingStandMaker.getStats() return {ironStock=MoldDryingStandMaker.ironStock,bronzeStock=MoldDryingStandMaker.bronzeStock,woodStock=MoldDryingStandMaker.woodStock,leatherStock=MoldDryingStandMaker.leatherStock,silverStock=MoldDryingStandMaker.silverStock,goldStock=MoldDryingStandMaker.goldStock,jewelStock=MoldDryingStandMaker.jewelStock,pearlStock=MoldDryingStandMaker.pearlStock,productStock=MoldDryingStandMaker.productStock,numBuildings=#MoldDryingStandMaker.buildings,hasMaker=MoldDryingStandMaker.maker~=nil,makerName=MoldDryingStandMaker.maker and MoldDryingStandMaker.maker.name or "—",makerSkill=MoldDryingStandMaker.maker and MoldDryingStandMaker.maker.skill or 0,activeMaking=#MoldDryingStandMaker.activeMaking,totalProducts=MoldDryingStandMaker.totalProducts} end
return MoldDryingStandMaker
